/* Ilocano Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Maria": "The most common feminine name in Ilocandia.", "Jose": "God increases — Hebrew Yosef, via Spanish", "Juan": "God is gracious — Hebrew Yohanan, via Spanish", "Rosa": "rose — Latin, via Spanish", "Pedro": "rock, stone — Greek petros, via Spanish", "Ana": "grace — Hebrew Hannah, via Spanish", "Marcos": "Ilocano family name of Ferdinand Marcos, from the 1849 Claveria surname decree.", "Singson": "Great Ilocos Sur political family name.", "Crisologo": "A historic Ilocano family name.", "Farinas": "A prominent Ilocos Norte family name."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Maria';
console.log(lookup(q));

